  // one or more keyword tags therefore carries no instruction of its own. Cards print them joined
  // without a separator (「[2回ブロック][インパクト無効]」), so every group must be a known tag.
  const tagGroups = text.match(/\[[^\]]+\]/g);
  if (tagGroups && tagGroups.join('') === text && tagGroups.every(tag => KEYWORD_TAGS.some(k => k.pattern.test(tag.slice(1, -1))))) return [];
