    const replayBaseUnion = text.match(/^この(?:キャラ|カード)のレイド元のカードが持つ(?<tags>(?:[\[［][^\]］]+[\]］](?:か[\[［][^\]］]+[\]］])*))をこの(?:キャラ|カード)が発動(する|してもよい)$/);
