        if (DYNAMIC_CEILING.test(`${m.groups!.pre ?? ''}${m.groups!.mid ?? ''}`)) return undefined;
        if (new RegExp(`(?:自分の|相手の)(?:${Object.keys(ZONE_OF).join('|')})`).test(`${m.groups!.pre ?? ''}${m.groups!.mid ?? ''}`)) return undefined;
