          const filter = parseFilter([subject]);
          if (!Object.keys(filter).length || unreadQualifier(filter, subject)) return undefined;
          steps.push({ type: 'select', bind: 'A', zone: 'ownSideline', filter, min: 0, max: 1, restOptional: true });
          steps.push({ type: 'act', target: 'A', operation: m.groups!.rest ? 'deployRested' : 'deploy', ...(m[4] === 'フロントL' ? { line: 'front' as const } : {}) });
