  if (leaveProtection) {
    const routes = leaveProtectionRoutes(leaveProtection.groups!.routes!);
    if (routes) return push(routes.length ? routes.map(source => ({ type: 'doesNotLeaveField' as const, source })) : [{ type: 'doesNotLeaveField' }]);
  }
